export function isSameOriginMediaSource(e,t){if(typeof e!="string"||!e)return!1;if(e.startsWith("blob:")||e.startsWith("data:")||e.startsWith("about:"))return!0;if(e.startsWith("//")||typeof t!="string"||!t)return!1;try{const n=new URL(e,t);return n.origin==="null"?!1:n.origin===t}catch{return!1}}export function resolveGainVolume(e){const t=Number(e);return Number.isFinite(t)?Math.max(0,Math.min(1,t)):0}export function createGainChain(e,t){if(!e||!t||typeof e.createMediaElementSource!="function"||typeof e.createGain!="function")return null;try{const n=e.createMediaElementSource(t),r=e.createGain();return r.gain.value=1,n.connect(r),r.connect(e.destination),{source:n,gain:r}}catch{return null}}export function resumeIfSuspended(e){try{if(e&&e.state==="suspended"&&typeof e.resume=="function"){const t=e.resume();t&&typeof t.catch=="function"&&t.catch(()=>{})}}catch{}}export function nextPlayableIndex(e,t,n,r){const u=Array.isArray(e)?e.length:0;if(!u||typeof r!="function")return-1;const o=(n|0)>=0?1:-1;for(let i=1;i<=u;i++){const a=((t+o*i)%u+u)%u;if(r(e[a]))return a}return-1}
